// @vitest-environment node
import { readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { describe, expect, it } from "vitest";

import { COMPANY } from "@/lib/company";
import { DOMINIO_POR_DEFECTO, RUTAS_PUBLICAS } from "@/lib/rutas-publicas";
import { PAGES } from "@/lib/seo";
import { mainServices } from "@/lib/servicios";
import { generarLlmsTxt } from "../../scripts/llms-txt.mjs";

/**
 * /llms.txt: what some AI assistants read to understand the site. Optional
 * (Google ignores it). It is GENERATED by scripts/generar-sitemap.mjs from the
 * same sources as the sitemap, so it cannot drift. It only repeats what the
 * site already publishes.
 */
const root = resolve(__dirname, "../..");
const read = (path: string) => readFileSync(join(root, path), "utf8");
const llms = read("public/llms.txt");

const sitemapUrls = [...read("public/sitemap.xml").matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);
const linkedUrls = [...llms.matchAll(/\]\((https?:[^)\s]+)\)/g)].map((m) => m[1]);
const bareUrls = [...llms.matchAll(/https?:\/\/[^\s)>\]]+/g)].map((m) => m[0]);

describe("llms.txt format", () => {
  it("starts with the company name as H1 and a blockquote summary", () => {
    expect(llms).toMatch(new RegExp(`^# ${COMPANY.name}\\n\\n> .+`));
    expect(llms).toContain(`> ${PAGES.home.description}`);
  });

  it("is plain text ending with a newline", () => {
    expect(llms.endsWith("\n")).toBe(true);
    expect(llms).not.toMatch(/<[a-z!][^>]*>/i);
  });
});

describe("llms.txt links", () => {
  it("links only URLs that are in the sitemap, all on the www domain", () => {
    expect(linkedUrls.length).toBeGreaterThan(0);
    for (const url of linkedUrls) {
      expect(sitemapUrls).toContain(url);
      expect(url.startsWith(DOMINIO_POR_DEFECTO)).toBe(true);
    }
  });

  it("mentions no URL outside the sitemap, except the sitemap file itself", () => {
    for (const url of bareUrls) {
      expect([...sitemapUrls, `${DOMINIO_POR_DEFECTO}/sitemap.xml`]).toContain(url);
    }
  });

  it("links every indexable page and no noindex page", () => {
    for (const ruta of RUTAS_PUBLICAS) expect(linkedUrls).toContain(`${DOMINIO_POR_DEFECTO}${ruta}`);
    expect(llms).not.toMatch(/\/baja|\/agenteActivado/);
  });
});

describe("llms.txt content", () => {
  it("names the company and lists the four services with their published descriptions", () => {
    expect(llms).toContain(COMPANY.name);
    expect(mainServices).toHaveLength(4);
    const ia = (s: string) => s.replace(/\bAI\b/g, "IA");
    for (const service of mainServices) {
      expect(llms).toContain(`- ${ia(service.title)}: ${ia(service.description)}`);
    }
  });

  it("gives the contact data of the single source", () => {
    expect(llms).toContain(COMPANY.email);
    expect(llms).toContain(COMPANY.phoneDisplay);
  });

  it("uses IA, never AI, as decided", () => {
    expect(llms).not.toMatch(/\bAI\b/);
    expect(llms).toContain("IA");
  });

  it("has no address, no city and no prices or invented claims", () => {
    expect(llms).not.toMatch(/\b(madrid|barcelona|valencia|sevilla|majadahonda|calle|c\/|avenida|avda|c\.p\.|código postal)\b/i);
    expect(llms).not.toMatch(/€|\bGRATIS\b/);
    expect(llms).not.toMatch(/testimonio|cliente[s]? como|\d+\s?%/i);
  });

  it("does not include the legal name of the person behind the company", () => {
    expect(llms).not.toContain(COMPANY.legalName);
  });
});

describe("generarLlmsTxt", () => {
  const seoSource = read("src/lib/seo.ts");
  const rutasSource = read("src/lib/rutas-publicas.ts");
  const serviciosSource = read("src/lib/servicios.ts");
  const companySource = read("src/lib/company.ts");
  const args = { seoSource, rutasSource, serviciosSource, companySource, rutas: [...RUTAS_PUBLICAS] };

  it("produces exactly the committed public/llms.txt", () => {
    expect(generarLlmsTxt(args)).toBe(llms);
  });

  it("only links the routes it is given", () => {
    const text = generarLlmsTxt({ ...args, rutas: ["/", "/avisolegal"] });
    const urls = [...text.matchAll(/\]\((https?:[^)\s]+)\)/g)].map((m) => m[1]);
    expect(urls).toEqual([`${DOMINIO_POR_DEFECTO}/`, `${DOMINIO_POR_DEFECTO}/avisolegal`]);
  });

  it("fails loudly when a source cannot be read", () => {
    expect(() => generarLlmsTxt({ ...args, serviciosSource: "export const x = 1;" })).toThrow(/servicios/);
  });
});
